# Simplest swap: right (7 cols at 18-24) then left (15 cols at 0-14)
# Result: 22 cols actual, pad to 25

def swap_segments_simple(grid, height=21, width=25):
    output = [[0] * width for _ in range(height)]

    for r in range(height):
        # Right segment goes to first 7 positions
        for c in range(7):
            output[r][c] = grid[r][c + 18]

        # Left segment goes to next 15 positions (7-21)
        for c in range(15):
            output[r][c + 7] = grid[r][c]

    return output

