# Fix bounds - when removing 2 columns from 25, we get 23 columns
# Original column 24 should go to position 22, so for c >= 17:
# Output col c maps to grid col c+2, but c+2 <= 22 means c <= 20

def remove_gap_columns(grid, height=21):
    gap_indices = [15, 17]
    output = [[0] * (height * 23 // height) if hasattr(height, '__mul__') else [0]*23 for _ in range(height)]

    width_out = 23

    for r in range(height):
        for c in range(width_out):
            if c < 15:
                grid_c = c
            elif c == 15:
                grid_c = 16
            elif c < 17:
                grid_c = c + 1
            else:  # c >= 17, includes up to 22
                grid_c = c + 2
            output[r][c] = grid[r][grid_c]

    return output

